package main

import (
  "context"
  "fmt"
  "log"
  "os"
  "github.com/jackc/pgx/v5/pgxpool"
)

func main() {
  ctx := context.Background()
  pool, err := pgxpool.New(ctx, os.Getenv("DATABASE_URL"))
  if err != nil { log.Fatal(err) }
  defer pool.Close()
  if err := pool.Ping(ctx); err != nil { log.Fatal(err) }

  var id int64
  err = pool.QueryRow(ctx,
    "INSERT INTO users (email, name) VALUES ($1, $2) RETURNING id",
    "ada@example.test", "Ada",
  ).Scan(&id)
  if err != nil { log.Fatal(err) }
  var email, name string
  err = pool.QueryRow(ctx, "SELECT email, name FROM users WHERE id = $1", id).Scan(&email, &name)
  if err != nil { log.Fatal(err) }
  fmt.Println(id, email, name)
}

rows, err := pool.Query(ctx,
  "SELECT id, email FROM users WHERE name ILIKE $1 ORDER BY id LIMIT $2", "A%", 20)
if err != nil { return err }
defer rows.Close()
for rows.Next() {
  var id int64
  var email string
  if err := rows.Scan(&id, &email); err != nil { return err }
  fmt.Println(id, email)
}
if err := rows.Err(); err != nil { return err }
tx, err := pool.Begin(ctx)
if err != nil { return err }
defer tx.Rollback(ctx)
_, err = tx.Exec(ctx, "UPDATE users SET name = $1 WHERE id = $2", "Ada Lovelace", 1)
if err != nil { return err }
return tx.Commit(ctx)

using Npgsql;

var connectionString = Environment.GetEnvironmentVariable("DATABASE_URL")
    ?? throw new InvalidOperationException("DATABASE_URL is required");
await using var dataSource = NpgsqlDataSource.Create(connectionString);
await using (var create = dataSource.CreateCommand(
    "INSERT INTO users (email, name) VALUES ($1, $2) RETURNING id"))
{
    create.Parameters.AddWithValue("email", "ada@example.test");
    create.Parameters.AddWithValue("name", "Ada");
    var id = (long)(await create.ExecuteScalarAsync())!;
    await using var find = dataSource.CreateCommand("SELECT name FROM users WHERE id = $1");
    find.Parameters.AddWithValue("id", id);
    Console.WriteLine(await find.ExecuteScalarAsync());
}

await using (var list = dataSource.CreateCommand(
    "SELECT id, email FROM users WHERE name ILIKE $1 ORDER BY id LIMIT $2"))
{
    list.Parameters.AddWithValue("prefix", "A%");
    list.Parameters.AddWithValue("limit", 20);
    await using var reader = await list.ExecuteReaderAsync();
    while (await reader.ReadAsync())
        Console.WriteLine($"{reader.GetInt64(0)} {reader.GetString(1)}");
}
await using var connection = await dataSource.OpenConnectionAsync();
await using var tx = await connection.BeginTransactionAsync();
try
{
    await using var update = new NpgsqlCommand(
        "UPDATE users SET name = $1 WHERE id = $2", connection, tx);
    update.Parameters.AddWithValue("name", "Ada Lovelace");
    update.Parameters.AddWithValue("id", 1L);
    await update.ExecuteNonQueryAsync();
    await tx.CommitAsync();
}
catch
{
    await tx.RollbackAsync();
    throw;
}

