import (
  "context"
  "fmt"
  "log"
  "os"
  "go.mongodb.org/mongo-driver/v2/bson"
  "go.mongodb.org/mongo-driver/v2/mongo"
  "go.mongodb.org/mongo-driver/v2/mongo/options"
)
type User struct { Email string `bson:"email"`; Name string `bson:"name"` }
func main() {
  ctx := context.Background()
  client, err := mongo.Connect(options.Client().ApplyURI(os.Getenv("MONGODB_URI")))
  if err != nil { log.Fatal(err) }
  defer client.Disconnect(ctx)
  if err := client.Ping(ctx, nil); err != nil { log.Fatal(err) }
  users := client.Database("app").Collection("users")
  result, err := users.InsertOne(ctx, User{Email: "ada@example.test", Name: "Ada"})
  if err != nil { log.Fatal(err) }
  var user User
  if err := users.FindOne(ctx, bson.D{{Key: "_id", Value: result.InsertedID}}).Decode(&user); err != nil { log.Fatal(err) }
  fmt.Println(user)
}

cursor, err := users.Find(ctx, bson.D{{Key: "name", Value: bson.D{{Key: "$regex", Value: "^A"}}}},
  options.Find().SetSort(bson.D{{Key: "_id", Value: 1}}).SetLimit(20))
if err != nil { return err }
defer cursor.Close(ctx)
for cursor.Next(ctx) {
  var user User
  if err := cursor.Decode(&user); err != nil { return err }
  fmt.Println(user)
}
if err := cursor.Err(); err != nil { return err }
_, err = users.UpdateOne(ctx, bson.D{{Key: "email", Value: "ada@example.test"}},
  bson.D{{Key: "$set", Value: bson.D{{Key: "name", Value: "Ada Lovelace"}}}})
if err != nil { return err }

pipeline := mongo.Pipeline{bson.D{{Key: "$group", Value: bson.D{
  {Key: "_id", Value: "$name"},
  {Key: "count", Value: bson.D{{Key: "$sum", Value: 1}}},
}}}}
counts, err := users.Aggregate(ctx, pipeline)
if err != nil { return err }
defer counts.Close(ctx)
for counts.Next(ctx) {
  fmt.Println(counts.Current)
}
return counts.Err()

