using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using MongoDB.Driver;

var uri = Environment.GetEnvironmentVariable("MONGODB_URI")
    ?? throw new InvalidOperationException("MONGODB_URI is required");
var client = new MongoClient(uri);
var db = client.GetDatabase("app");
await db.RunCommandAsync<BsonDocument>(new BsonDocument("ping", 1));
var users = db.GetCollection<User>("users");
var user = new User { Email = "ada@example.test", Name = "Ada" };
await users.InsertOneAsync(user);
Console.WriteLine((await users.Find(x => x.Id == user.Id).FirstOrDefaultAsync())?.Name);

public sealed class User
{
    [BsonId] public ObjectId Id { get; set; }
    public string Email { get; set; } = "";
    public string Name { get; set; } = "";
}

var page = await users.Find(x => x.Name.StartsWith("A"))
    .SortBy(x => x.Id).Limit(20).ToListAsync();
await users.UpdateOneAsync(x => x.Email == "ada@example.test",
    Builders<User>.Update.Set(x => x.Name, "Ada Lovelace"));
var counts = await users.Aggregate()
    .Group(x => x.Name, group => new { Name = group.Key, Count = group.Count() })
    .SortByDescending(x => x.Count).Limit(10).ToListAsync();
Console.WriteLine($"{page.Count} users, {counts.Count} groups");

